class AsyncOperations:
    """One typed method per endpoint. Mixed into the client; see `AsyncHandlesApi`."""

    async def _op(self, name: str, args: Mapping[str, Any], timeout: Optional[float] = None) -> Any:
        raise NotImplementedError

    async def accounts_platforms(
        self,
        *,
        timeout: Optional[float] = None,
    ) -> Response[AccountsPlatformsData]:
        """What a check can answer, per platform.
        
        `GET /accounts/platforms`. 1 credit.
        """
        return await self._op("accounts_platforms", {}, timeout)  # type: ignore[no-any-return]

    async def accounts_check(
        self,
        platform: Literal["x", "instagram", "tiktok", "youtube", "telegram", "bluesky", "kick", "twitch", "linkedin"],
        handle: str,
        *,
        timeout: Optional[float] = None,
    ) -> Response[AccountsCheckData]:
        """Check one account against our catalog.
        
        `GET /accounts/{platform}/{handle}`. 1 credit.
        
        Args:
            platform: Which platform the handle belongs to.
            handle: The account handle, with or without the @. Bluesky handles are domains and a bare name is completed to <name>.bsky.social. LinkedIn takes the company slug.
        """
        return await self._op("accounts_check", {"platform": platform, "handle": handle}, timeout)  # type: ignore[no-any-return]

