    async def directory_list(
        self,
        platform: Literal["x", "telegram", "bluesky", "youtube", "tiktok", "instagram", "kick", "twitch"],
        *,
        limit: Optional[int] = None,
        cursor: Optional[str] = None,
        sort: Optional[str] = None,
        order: Optional[Literal["asc", "desc"]] = None,
        q: Optional[str] = None,
        search: Optional[str] = None,
        fields: Optional[str] = None,
        scope: Optional[Literal["addressable", "all"]] = None,
        min_followers: Optional[int] = None,
        country: Optional[str] = None,
        language: Optional[str] = None,
        category: Optional[str] = None,
        timeout: Optional[float] = None,
    ) -> Response[DirectoryListData]:
        """List and filter a catalog.
        
        `GET /directory/{platform}`. 1 credit.
        
        Args:
            platform: Which catalog to read.
            limit: Rows per page, 1 to 500.
            cursor: Opaque keyset position from meta.page.next_cursor. Signed; a hand-written cursor is rejected.
            sort: Sort key. `id` walks the primary key and is the cheapest full-corpus order; the platform's audience metric (followers / subscribers) is the default and is...
            order: Sort direction.
            q: Full-text search over name and bio, served by the catalog's GIN index. Available on X, Instagram, TikTok, YouTube and Telegram; Bluesky has no such index and...
            search: Substring match on handle and display name. Unindexed by construction, so it is applied inside the audience-ordered candidate window rather than to the whole...
            fields: Comma-separated projection. Any field listed by GET /directory for that platform, plus weekly_growth. Omitting weekly_growth skips a per-row snapshot lookup.
            scope: `addressable` (default) is the active, non-NSFW, handled catalog - the rows a public page can link to, and the only scope the ranked indexes cover. `all` is...
            min_followers: Audience floor. Every platform has a min/max pair on its own metric: min_followers (X, Bluesky, TikTok), min_participants (Telegram), min_subscribers (YouTube).
            country: ISO 3166-1 alpha-2, as inferred by the engine's geo classifier. Not available on TikTok.
            language: ISO 639-1, as inferred by the engine's language classifier.
            category: Topic category slug.
        """
        return await self._op("directory_list", {"platform": platform, "limit": limit, "cursor": cursor, "sort": sort, "order": order, "q": q, "search": search, "fields": fields, "scope": scope, "min_followers": min_followers, "country": country, "language": language, "category": category}, timeout)  # type: ignore[no-any-return]

