    async def leads_linkedin_segments(
        self,
        *,
        by: Optional[Literal["industry", "country", "size_band", "founded_decade"]] = None,
        industry: Optional[str] = None,
        country: Optional[str] = None,
        size_band: Optional[str] = None,
        min_staff: Optional[int] = None,
        max_staff: Optional[int] = None,
        timeout: Optional[float] = None,
    ) -> Response[LeadsLinkedinSegmentsData]:
        """Firmographic market sizing with real counts.
        
        `GET /leads/linkedin/segments`. 1 credit.
        
        Args:
            by: Dimension to group on.
            industry: Restrict to one industry, exactly as LinkedIn writes it.
            country: ISO 3166-1 alpha-2. Matched against country_code, never the free text.
            size_band: LinkedIn size band, e.g. '51-200 employees'.
            min_staff: Lower bound on exact headcount. Companies with no headcount are excluded.
            max_staff: Upper bound on exact headcount. Companies with no headcount are excluded.
        """
        return await self._op("leads_linkedin_segments", {"by": by, "industry": industry, "country": country, "size_band": size_band, "min_staff": min_staff, "max_staff": max_staff}, timeout)  # type: ignore[no-any-return]

    async def leads_linkedin_companies_list(
        self,
        *,
        country: Optional[str] = None,
        industry: Optional[str] = None,
        size: Optional[str] = None,
        has_email: Optional[bool] = None,
        has_website: Optional[bool] = None,
        has_decision_maker: Optional[bool] = None,
        has_social: Optional[bool] = None,
        min_followers: Optional[int] = None,
        active_days: Optional[int] = None,
        q: Optional[str] = None,
        sort: Optional[Literal["followers", "readiness", "recent", "staff"]] = None,
        limit: Optional[int] = None,
        cursor: Optional[str] = None,
        timeout: Optional[float] = None,
    ) -> Response[LeadsLinkedinCompaniesListData]:
        """LinkedIn company records, filterable.
        
        `GET /leads/linkedin/companies`. 1 credit.
        
        Args:
            country: ISO 3166-1 alpha-2, derived by the engine from the free-text location. LinkedIn writes 'City, Region' and rarely names a country, so filter on this rather than...
            industry: Industry exactly as LinkedIn labels it.
            size: Employee band exactly as LinkedIn labels it. Applied inside the scan window - see the pagination note.
            has_email: Only companies with at least one non-suppressed contact address.
            has_website: Only companies with a resolved website domain. Applied inside the scan window.
            has_decision_maker: Only companies where we can name a founder, C-level, VP or director.
            has_social: Only companies with a social handle that matched a row in one of our catalogs.
            min_followers: LinkedIn follower floor.
            active_days: Only companies that posted within this many days.
            q: Substring match on company name, slug or website domain.
            sort: readiness orders by the columns the contactability score is built from, then applies the exact score to the page.
            limit: Rows per page, 1-200.
            cursor: Opaque cursor from meta.page.next_cursor.
        """
        return await self._op("leads_linkedin_companies_list", {"country": country, "industry": industry, "size": size, "has_email": has_email, "has_website": has_website, "has_decision_maker": has_decision_maker, "has_social": has_social, "min_followers": min_followers, "active_days": active_days, "q": q, "sort": sort, "limit": limit, "cursor": cursor}, timeout)  # type: ignore[no-any-return]

