        return await self._op("leads_linkedin_people_list", {"company": company, "seniority": seniority, "decision_makers": decision_makers, "title": title, "country": country, "industry": industry, "limit": limit, "cursor": cursor}, timeout)  # type: ignore[no-any-return]
